def copy_round_off(apps, schema_editor):
    """One money row per company, for its own country: 3 decimals (as today)
    and the round-off most of its stations use (Device Settings), else
    upward 0.25. The admin then sets BYKY UAE to 2 decimals."""
    Company = apps.get_model("company", "Company")
    Setting = apps.get_model("company", "CompanyMoneySetting")
    DeviceSettings = apps.get_model("devices", "DeviceSettings")
    for company in Company.objects.all():
        used = Counter(DeviceSettings.objects.filter(company_id=company.pk)
                       .values_list("round_off_mode", "round_off_step"))
        mode, step = used.most_common(1)[0][0] if used else ("upward", Decimal("0.25"))
        Setting.objects.get_or_create(company_id=company.pk, country_id=company.country_id, defaults={
            "decimal_places": 3, "round_off_mode": mode, "round_off_step": step})


